  function parseLocalDateTime(value){const v=String(value||'').trim(),m=/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/.exec(v);if(!m)return '';const ms=Date.parse(m[1]+'-'+m[2]+'-'+m[3]+'T'+m[4]+':'+m[5]+':'+m[6]+'+08:00');if(!Number.isFinite(ms))return '';const iso=new Date(ms).toISOString();return localDate(iso)===v?iso:'';}
