  function registerTeacherCatalogTemplate(title,category){const matches=TEACHER_SYSTEM_TEMPLATES.filter(t=>t.title===title);if(matches.length){for(const t of matches){t.categories=[...new Set([...(t.categories||[t.category]),category])];}return;}const index=TEACHER_SYSTEM_TEMPLATES.length+1;TEACHER_SYSTEM_TEMPLATES.push({id:'catalog-'+index,title,category,categories:[category],flag:'',tone:category==='健康安全'?'health':category==='节日活动'||category==='放假通知'?'peach':'green',icon:title.slice(0,1),kind:'ordinary',body:'',sourceBodyCaptured:false});}
