  function teacherTemplateCardsHTML(){const query=(S.templateQuery||'').trim().toLowerCase();let rows;if(S.templateCategory==='我的模板'){rows=DB.templates.filter(t=>t.schoolId===S.schoolId).map(t=>({id:'custom:'+t.id,title:t.title,flag:'我的模板',tone:'custom',icon:'文',kind:'beautiful',body:''}));}else{rows=TEACHER_SYSTEM_TEMPLATES.filter(t=>S.templateCategory==='热门推荐'?(t.flag==='热门'||t.flag==='NEW'):(t.categories||[t.category]).includes(S.templateCategory)).map(t=>({...t,id:'system:'+t.id}));}if(query)rows=rows.filter(t=>(t.title+' '+(t.body||'')+' '+(t.categories||[t.category]).join(' ')).toLowerCase().includes(query));if(!rows.length)return '<div class="template-empty">'+(S.templateCategory==='我的模板'?'暂无我的模板':'没有匹配的模板')+'</div>';return rows.map(t=>'<button class="template-list-item" data-action="template-preview" data-value="'+esc(t.id)+'"><span class="template-thumb template-thumb--'+esc(t.tone)+'">'+esc(t.icon)+'</span><span class="template-item-copy">'+(t.flag?'<small class="template-flag '+(t.flag==='NEW'?'new':'')+'">'+esc(t.flag)+'</small>':'')+'<strong>'+esc(t.title)+'</strong></span></button>').join('');}
