  function teacherTemplatePreviewPhone(){const found=resolveTeacherTemplate(S.templatePreview),t=found?.template;if(!t)return mobileFrame('通知模板','<div class="empty-state">模板不存在</div>','','template-back');const n=found.kind==='custom'?t:(()=>{const x=C.empty(actor());x.title=t.title;x.blocks=[C.textBlock(t.body)];x.cover='';x.attachments=[];return x;})();const body=found.kind==='system'&&!t.sourceBodyCaptured?'<p class="template-body-missing">该模板仅收录标题，正文未转录</p>':contentHTML(n);return mobileFrame(school().name,'<div class="mobile-inner"><article class="article template-preview-article"><h1>'+esc(t.title)+'</h1><div class="meta"><span>来自：'+esc(found.kind==='custom'?t.by||'我的模板':'系统模板')+'</span></div>'+((found.kind==='custom'&&t.cover)?'<img class="cover" src="'+esc(safeURL(t.cover))+'" alt="通知封面">':'')+body+'</article></div>','<div class="mobile-action"><button class="btn primary" data-action="template-use" data-value="'+esc(S.templatePreview)+'">使用模板</button></div>','template-back');}
