  function openBeautifulBackground(){const options=[['plain','简洁白底'],['fresh','清新绿底'],['letter','暖色信纸']];modalData={type:'beautiful-background'};$('#modal-root').innerHTML='<div class="dialog-mask mobile-dialog beautiful-sheet-mask"><section class="dialog beautiful-background-sheet" role="dialog" aria-modal="true" aria-label="选择预览背景"><div class="beautiful-sheet-handle"></div><div class="dialog-head"><h2>选择预览背景</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">'+icon('close')+'</button></div><div class="dialog-body beautiful-theme-options">'+options.map(([v,t])=>'<button data-action="select-beautiful-theme" data-value="'+v+'" class="beautiful-theme-choice '+(S.draft?.theme===v?'selected':'')+'"><span class="theme-sample theme-'+v+'">Aa</span><span>'+t+'</span>'+(S.draft?.theme===v?'<b>✓</b>':'')+'</button>').join('')+'</div></section></div>';}  function teacherPhone(){if(S.page==='template-picker')return teacherTemplatePickerPhone();if(S.page==='template-preview')return teacherTemplatePreviewPhone();if(S.page==='edit')return S.beautifulPreview?beautifulPreviewPhone():teacherEditPhone();if(S.page==='detail'){const n=getN(S.id);if(!n||!C.canView(actor(),n))return mobileFrame('通知详情','<div class="empty-state">无权限查看此通知</div>','','back');const can=C.canEdit(actor(),n),lock=C.locked(n)&&n.status==='published',rec=C.recipients(n).teachers.includes(actor().id)&&n.status==='published';return mobileFrame('通知详情','<div class="mobile-inner"><div class="mobile-card">'+articleHTML(n)+'</div><div class="mobile-card"><h3 style="font-size:12px">通知信息</h3>'+[['来源',C.roleNames[n.origin]+' · '+n.creatorName],['最近修改',n.lastEditor||n.creatorName],['发布对象',audienceText(n)],['查收方式',C.ackNames[n.config.ack]],['状态',C.stateNames[n.status]]].map(([k,v])=>'<div class="info-pair"><span>'+k+'</span><span>'+esc(v)+'</span></div>').join('')+'<div class="row wrap" style="margin-top:14px"><button class="link" data-action="copy" data-id="'+n.id+'">复制使用</button><button class="link" data-action="save-template" data-id="'+n.id+'">存为模板</button>'+(n.status==='scheduled'&&can?'<button class="link" data-action="cancel-schedule" data-id="'+n.id+'">取消定时</button>':'')+(C.canManage(actor(),n)?'<button class="link danger" data-action="delete" data-id="'+n.id+'">删除</button>':'')+'</div></div>'+(rec?'<div class="mobile-card"><h3 style="font-size:12px">我收到的教师通知</h3>'+receiverAction(n,true)+'</div>':'')+'</div>','<div class="mobile-action"><div class="row"><button class="btn" data-action="stats" data-id="'+n.id+'" '+(!['published','deleted'].includes(n.status)?'disabled':'')+'>阅读统计</button>'+(can?'<button class="btn primary" data-action="'+(lock?'supplement':'edit')+'" data-id="'+n.id+'">'+(lock?'补充说明':'修改通知')+'</button>':'')+'</div></div>','back');}
    const list=visibleList(),allCount=DB.notices.filter(n=>C.canView(actor(),n)&&n.status!=='deleted').length,mineCount=DB.notices.filter(n=>n.creator===actor().id&&n.status!=='deleted').length,receivedCount=DB.notices.filter(n=>n.status==='published'&&C.recipients(n).teachers.includes(actor().id)).length,draftCount=DB.notices.filter(n=>n.creator===actor().id&&n.status==='draft').length;const counts={all:allCount,mine:mineCount,received:receivedCount,draft:draftCount};return mobileFrame('校园通知','<div class="mobile-inner"><div class="mobile-tabs">'+[['all','学校通知'],['mine','我发布'],['received','我接收'],['draft','草稿箱']].map(([v,t])=>'<button data-action="tab" data-value="'+v+'" class="'+(S.tab===v?'active':'')+'">'+t+'（'+counts[v]+'）</button>').join('')+'</div><div class="mobile-search">'+icon('search')+'<input data-input="query" aria-label="老师通知搜索" placeholder="搜索标题 / 创建人" value="'+esc(S.query)+'"><button class="icon-btn" data-action="search" aria-label="搜索">↵</button></div><div class="row between"><small style="font-size:10px">共 '+list.length+' 条通知</small></div>'+list.map(n=>{const c=C.counts(n);if(S.tab==='received'){const f=familyReceipt(n,true),state=n.config.ack!=='read'&&!f.done&&Date.now()>C.deliveryUntil(n)?'已截止':n.config.ack==='read'?(f.read?'已读':'请阅读通知'):n.config.ack==='confirm'?(f.done?'已确认':f.read?'请点击确认':'请阅读通知'):(f.done?'已签字':f.read?'请签字确认':'请阅读通知');return '<article class="mobile-card mobile-notice-compact"><button class="mobile-notice-open" data-action="detail" data-id="'+n.id+'"><span class="mobile-notice-cover">'+(n.cover?'<img src="'+esc(safeURL(n.cover))+'" alt="封面">':'<span>通</span>')+'</span><span class="mobile-notice-info"><strong>'+esc(n.title)+'</strong><small>来自：'+esc(fromName(n))+'</small><small>'+dateOnly(n.publishedAt)+'</small><em class="notice-state">'+state+' ›</em></span></button></article>';}return '<div class="mobile-card" data-notice="'+n.id+'"><div class="row between"><span class="meta">'+esc(fromName(n))+'</span>'+badge(n)+'</div>'+(n.cover?'<img class="thumb" src="'+esc(safeURL(n.cover))+'" alt="通知封面">':'')+'<h3><button data-action="detail" data-id="'+n.id+'" style="font:inherit;color:inherit;border:0;background:none;text-align:left;padding:0">'+esc(n.title)+'</button></h3><div class="summary">'+esc(summary(n))+'</div><div class="row wrap" style="gap:5px;margin-bottom:8px"><span class="badge blue">'+C.ackNames[n.config.ack]+'</span><span class="muted" style="font-size:10px">'+contentKinds(n)+' · '+esc(C.roleNames[n.origin])+'</span>'+(n.updated?'<span class="badge orange">已更新</span>':'')+'</div><div class="card-bottom"><span>'+ (n.status==='scheduled'?fmt(n.config.scheduledAt,true)+' 定时':n.status==='draft'?'待发布':c.students.read+'/'+c.students.total+' 学生已读'+(c.teachers.total?' · 教师'+c.teachers.read+'/'+c.teachers.total:''))+'</span><button class="link" data-action="detail" data-id="'+n.id+'">查看详情 ›</button></div></div>';}).join('')+(!list.length?'<div class="empty-state">暂无通知</div>':'')+'</div>','<div class="mobile-action"><button class="btn primary" data-action="new">发布通知</button></div>');}
  function parentActor(){return {...C.actor('parent',S.schoolId),childId:S.child};}
  function familyReceipt(n,teacher=false){const recipient=teacher?actor().id:S.child,kind=teacher?'teacher':'student';const rs=Object.values(n.receipts||{}).filter(r=>r.kind===kind&&r.recipientId===recipient);return {records:rs,read:rs.some(r=>r.readAt),done:n.config.ack==='read'?rs.some(r=>r.readAt):n.config.ack==='confirm'?rs.some(r=>r.confirmAt):rs.some(r=>r.signatures?.length),own:rs.find(r=>r.guardianId===(teacher?actor().id:'p1'))};}
  function parentPhone(){const a=parentActor(),child=C.children.find(c=>c.id===S.child),current=['detail','withdrawn'].includes(S.parentPage)?getN(S.parentId):null;const list=DB.notices.filter(n=>C.canView(a,n)).filter(n=>S.parentTab!=='todo'||!familyReceipt(n).done).sort((a,b)=>b.publishedAt-a.publishedAt);if(S.parentPage==='withdrawn'){const withdrawn=!!current&&current.status==='deleted'&&C.recipients(current).students.includes(a.childId);if(!withdrawn)return mobileFrame('通知详情','<div class="empty-state">通知不存在或不在当前孩子接收范围内</div>','','parent-back');return mobileFrame('通知已删除','<div class="mobile-inner"><section class="withdrawn-landing"><div class="withdrawn-icon" aria-hidden="true">×</div><span class="withdrawn-label">通知状态 · 已删除</span><h2>这条通知已删除</h2><p>无法查看原通知。</p><div class="withdrawn-meta"><div class="info-pair"><span>学校</span><span>'+esc(school().name)+'</span></div><div class="info-pair"><span>处理时间</span><span>'+fmt(current.deletedAt||current.updatedAt,true)+'</span></div></div></section></div>','<div class="mobile-action"><button class="btn" data-action="parent-back">通知列表</button></div>');}if(S.parentPage==='detail'){if(!current||!C.canView(a,current))return mobileFrame('通知详情','<div class="empty-state">通知不存在或不在当前孩子接收范围内</div>','','parent-back');const f=familyReceipt(current),rs=f.records;return mobileFrame('通知详情','<div class="mobile-inner"><div class="mobile-card" style="margin-top:3px">'+articleHTML(current)+'</div><div class="mobile-card"><h3 style="font-size:12px">我的查收状态 <span class="badge '+(f.done?'green':'orange')+'">'+(f.done?'已完成':'待完成')+'</span></h3><div class="info-pair"><span>当前学生</span><span>'+esc(child.name)+' · '+esc(C.classes.find(c=>c.id===child.classId).name)+'</span></div><div class="info-pair"><span>查收方式</span><span>'+C.ackNames[current.config.ack]+'</span></div>'+(f.own?.confirmAt?'<div class="info-pair"><span>我的确认</span><span>'+fmt(f.own.confirmAt,true)+' · V'+f.own.confirmVersion+'</span></div>':'')+(f.own?.signatures?.length?'<div class="receipt-card" style="padding:11px;margin-top:12px"><strong>我的回执</strong><small style="display:block">最新签字 · V'+f.own.signatures.at(-1).version+' · '+fmt(f.own.signatures.at(-1).at,true)+'</small><img class="signature-img" src="'+esc(safeURL(f.own.signatures.at(-1).image))+'" alt="我的签名"><br><button class="link" data-action="my-receipt" data-id="'+current.id+'">查看签字历史（'+f.own.signatures.length+'）</button></div>':'')+'</div><div class="mobile-card"><h3 style="font-size:12px">家人已读动态</h3>'+ (rs.length?rs.filter(r=>r.readAt).map(r=>'<div class="info-pair"><span>'+esc(r.guardian)+'</span><span>'+fmt(r.readAt,true)+' 已读</span></div>').join(''):'<p class="muted">暂无阅读记录</p>')+'</div></div>','<div class="mobile-action">'+receiverAction(current)+'</div>','parent-back');}
    const todo=DB.notices.filter(n=>C.canView(a,n)&&!familyReceipt(n).done).length,all=DB.notices.filter(n=>C.canView(a,n)).length;const statusText=n=>{const f=familyReceipt(n);if(n.config.ack!=='read'&&!f.done&&Date.now()>C.deliveryUntil(n))return '已截止';if(n.config.ack==='read')return f.read?'已读':'请阅读通知';if(n.config.ack==='confirm')return f.done?'已确认':f.read?'请点击确认':'请阅读通知';return f.done?'已签字':f.read?'请签字确认':'请阅读通知';};return mobileFrame('校园通知','<div class="mobile-inner"><div class="mobile-tabs"><button data-action="parent-tab" data-value="all" class="'+(S.parentTab==='all'?'active':'')+'">全部（'+all+'）</button><button data-action="parent-tab" data-value="todo" class="'+(S.parentTab==='todo'?'active':'')+'">待办（'+todo+'）</button></div>'+list.map(n=>'<article class="mobile-card mobile-notice-compact" data-parent-notice="'+n.id+'"><button class="mobile-notice-open" data-action="parent-detail" data-id="'+n.id+'"><span class="mobile-notice-cover">'+(n.cover?'<img src="'+esc(safeURL(n.cover))+'" alt="封面">':'<span>通</span>')+'</span><span class="mobile-notice-info"><strong>'+esc(n.title)+'</strong><small>来自：'+esc(fromName(n))+'</small><small>'+dateOnly(n.publishedAt)+'</small><em class="notice-state '+(!familyReceipt(n).done&&n.config.ack!=='read'?'pending':!familyReceipt(n).read?'pending':'')+'">'+statusText(n)+' ›</em></span></button></article>').join('')+(!list.length?'<div class="empty-state">'+icon('check')+'<p>'+(S.parentTab==='todo'?'当前孩子暂无待办':'暂无通知')+'</p></div>':'')+'</div>');}

  function receiverAction(n,teacher=false){const f=familyReceipt(n,teacher),ctx=teacher?'teacher':'parent';if(n.config.ack!=='read'&&!f.done&&Date.now()>C.deliveryUntil(n))return '<span class="badge orange">已截止</span>';if(n.config.ack==='read')return '<div class="row between"><span class="muted" style="font-size:11px">只需阅读查看</span><span class="badge green">'+icon('check')+'已阅读</span></div>';return '<small>'+(teacher?'当前教师：'+actor().name:'当前学生：'+C.children.find(c=>c.id===S.child).name)+' · '+(f.done?'已完成查收':'请阅读后完成查收')+'</small>'+(n.config.ack==='confirm'?'<button class="btn primary" data-action="confirm-receipt" data-id="'+n.id+'" data-value="'+ctx+'" '+(f.done?'disabled':'')+'>'+ (f.done?'已确认收到':'已收到')+'</button>':'<button class="btn primary" data-action="sign" data-id="'+n.id+'" data-value="'+ctx+'">'+ (f.done?'重新签字':'点击签字')+'</button>');}
  async function openParent(id){S.parentId=id;S.parentPage='detail';const res=await transaction(d=>C.receipt(d,id,parentActor(),'read'));if(!res.ok)toast(res.message);render();}
  async function detail(id){const n=getN(id);if(!n||!C.canView(actor(),n)){toast('无权限查看');return;}S.id=id;S.page='detail';if(S.role==='teacher'&&C.recipients(n).teachers.includes(actor().id)&&n.status==='published')await transaction(d=>C.receipt(d,id,actor(),'read'));render();scrollTo({top:0,behavior:'instant'});}
  let signContext=null;
  function sign(id,teacher=false){const n=getN(id),f=familyReceipt(n,teacher);signContext={id,teacher,version:n.version,drawn:false};modalData={type:'sign',id};showModal(f.done?'重新签字':'签字确认','<div class="receipt-card"><h3>'+esc(n.title)+'</h3><p style="margin-top:7px;font-size:12px">'+esc(school().name)+' · '+esc(teacher?actor().name:C.children.find(c=>c.id===S.child).name)+'</p><small>确认内容版本 V'+n.version+'</small></div><canvas id="signature-pad" class="signature-pad" aria-label="手写签名区域"></canvas>','<button class="btn" data-action="clear-sign">重写</button><button class="btn primary" data-action="submit-sign">提交签名</button>');bindSignature();}
  function bindSignature(){const c=$('#signature-pad');if(!c||c.dataset.bound)return;c.dataset.bound='1';const rect=c.getBoundingClientRect(),ratio=devicePixelRatio||1;c.width=Math.max(300,rect.width)*ratio;c.height=rect.height*ratio;const ctx=c.getContext('2d');ctx.scale(ratio,ratio);ctx.strokeStyle='#243e59';ctx.lineWidth=2.2;ctx.lineCap='round';ctx.lineJoin='round';let down=false;const point=e=>{const r=c.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top];};c.addEventListener('pointerdown',e=>{down=true;c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));});c.addEventListener('pointermove',e=>{if(!down)return;ctx.lineTo(...point(e));ctx.stroke();signContext.drawn=true;});c.addEventListener('pointerup',()=>down=false);c.addEventListener('pointercancel',()=>down=false);}
  async function submitSignature(){if(!signContext?.drawn){toast('请先手写签名');return;}const context={...signContext,image:$('#signature-pad').toDataURL('image/png')};confirm('确认提交签名？','提交后无法取消本次签名。','确认提交',async()=>{const a=context.teacher?actor():parentActor();const res=await transaction(d=>{if(d.notices.find(n=>n.id===context.id)?.version!==context.version)return {ok:false,message:'通知内容已更新，请重新阅读后签字。'};return C.receipt(d,context.id,a,'sign',context.image);});if(!res.ok){toast(res.message);return;}render();toast('签字成功');});}
  // 素材放入浏览器 IndexedDB，通知只保存素材 ID，多个同源标签页均可读取。
  let assetsDB,assetUrls=new Map();
  function openAssets(){return assetsDB||(assetsDB=new Promise((resolve,reject)=>{const r=indexedDB.open('campus-notice-v6-assets',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);}));}
  async function putAsset(file){const id=C.uid('asset'),db=await openAssets();await new Promise((resolve,reject)=>{const t=db.transaction('files','readwrite');t.objectStore('files').put(file,id);t.oncomplete=resolve;t.onerror=()=>reject(t.error);});return id;}
  async function getAssetUrl(id){if(assetUrls.has(id))return assetUrls.get(id);const db=await openAssets(),blob=await new Promise((resolve,reject)=>{const r=db.transaction('files').objectStore('files').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(!blob)throw new Error('素材已失效');const url=URL.createObjectURL(blob);assetUrls.set(id,url);return url;}
  async function hydrate(){for(const el of document.querySelectorAll('[data-asset]')){try{el.src=await getAssetUrl(el.dataset.asset);}catch{el.setAttribute('title','此浏览器中未找到对应素材，请重新选择。');}}}
  function pickFile(accept,multiple=false){return new Promise(resolve=>{const i=document.createElement('input');i.type='file';i.accept=accept;i.multiple=multiple;i.className='file-input';document.body.append(i);i.onchange=()=>{resolve([...i.files]);i.remove();};i.oncancel=()=>{resolve([]);i.remove();};i.click();});}
  async function uploadMedia(id){const b=S.draft?.blocks.find(b=>b.id===id);if(!b)return;const [f]=await pickFile({image:'image/*',video:'video/*',audio:'audio/*'}[b.type]);if(!f)return;if(!f.type.startsWith(b.type+'/')){toast('请选择正确类型的素材');return;}if(b.type==='image'&&f.size>10*1024*1024){toast('单张图片不能超过10MB');return;}if(b.type==='video'){const v=document.createElement('video'),url=URL.createObjectURL(f);v.src=url;const duration=await new Promise(resolve=>{v.onloadedmetadata=()=>resolve(v.duration);v.onerror=()=>resolve(NaN);});URL.revokeObjectURL(url);if(!Number.isFinite(duration)||duration>600){toast('请选择可播放且不超过10分钟的视频');return;}}try{b.asset=await putAsset(f);delete b.src;b.name=f.name;S.dirty=true;render();toast('素材已添加');}catch{toast('素材保存失败，请检查浏览器存储空间');}}
  async function uploadCover(){const [f]=await pickFile('image/*');if(!f)return;if(!f.type.startsWith('image/')||f.size>10*1024*1024){toast('请选择10MB以内的图片');return;}try{const img=await createImageBitmap(f),c=document.createElement('canvas'),ratio=Math.min(1,800/img.width);c.width=img.width*ratio;c.height=img.height*ratio;c.getContext('2d').drawImage(img,0,0,c.width,c.height);S.draft.cover=c.toDataURL('image/jpeg',.8);S.dirty=true;render();}catch{toast('无法读取这张图片');}}
  async function uploadFiles(){const accept='.pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,image/jpeg,image/png';const files=await pickFile(accept,true);if(!files.length)return;if(S.draft.attachments.length+files.length>9){toast('附件最多9份');return;}const allowed=/\.(pdf|docx?|xlsx?|jpe?g|png)$/i;if(files.some(f=>f.size>20*1024*1024||!allowed.test(f.name))){toast('支持PDF、Word、Excel、JPEG、JPG、PNG文件，每份不超过20MB');return;}try{for(const f of files)S.draft.attachments.push({id:C.uid('file'),asset:await putAsset(f),name:f.name,size:f.size});S.dirty=true;render();}catch{toast('附件保存失败，请检查存储空间');}}async function attachment(id,noticeId){const n=S.draft?.id===noticeId?S.draft:getN(noticeId),f=n?.attachments.find(f=>f.id===id);if(!f)return;try{const url=f.asset?await getAssetUrl(f.asset):f.src;if(!url){toast('附件暂不可用');return;}modalData={type:'attachment'};const image=/\.(jpe?g|png)$/i.test(f.name);showModal(f.name,image?'<img src="'+esc(url)+'" alt="'+esc(f.name)+'" style="display:block;max-width:100%;max-height:60vh;margin:auto;object-fit:contain">':/\.pdf$/i.test(f.name)?'<iframe title="附件预览" src="'+esc(url)+'" style="border:0;width:100%;height:58vh"></iframe>':'<div class="empty-state">'+icon('file')+'<p>'+esc(f.name)+'</p><a class="btn primary" href="'+esc(url)+'" download="'+esc(f.name)+'">下载附件</a></div>','<a class="btn primary" href="'+esc(url)+'" download="'+esc(f.name)+'">下载附件</a><button class="btn" data-action="close-modal">关闭预览</button>',true);}catch{toast('附件不可用，请重新添加');}}
  function applyPreset(type){if(type==='templates'){openTemplates();return;}const apply=()=>{S.draft.blocks=type==='plain'?[C.textBlock('')]:type==='image'?[C.textBlock(''),{id:C.uid('b'),type:'image',src:'assets/campus.svg',caption:''}]:type==='video'?[{id:C.uid('b'),type:'video',src:'assets/安全课堂.mp4',caption:''}]:[{id:C.uid('b'),type:'link',title:'',url:''}];S.dirty=true;render();};if(S.draft.blocks.some(b=>b.type!=='text'||b.text?.trim()))confirm('切换起稿方式？','当前未保存的正文块会被替换。标题、附件和发布设置保留。','替换正文',apply);else apply();}
  async function saveTemplate(id){const n=getN(id);if(!n)return;const result=await transaction(d=>{d.templates.unshift({id:C.uid('tpl'),schoolId:S.schoolId,title:n.title,kind:n.noticeKind,blocks:C.clone(n.blocks),attachments:C.clone(n.attachments),cover:n.cover,theme:n.theme,music:S.role==='teacher'?'':n.music,by:actor().name});d.revision++;return {ok:true};});toast(result.ok?'已保存为本校模板，发布时从“我的模板”套用':result.message);}
